package com.memme.service.auth;
import com.memme.dto.auth.*; import com.memme.entity.auth.SignupDraft; import com.memme.exception.*; import com.memme.repository.auth.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*; import java.util.regex.Pattern; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class SignupService { private static final Pattern EMAIL=Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"); private static final Pattern PHONE=Pattern.compile("^010\\d{8}$"); private static final Pattern PASSWORD=Pattern.compile("^(?=.*[A-Z])(?=.*[a-z])(?=.*\\d)(?=.*[^A-Za-z0-9]).{8,20}$"); private final UserRepository users; private final SignupDraftRepository drafts; private final PasswordEncoder encoder; private final Clock clock; private final SecureRandom random=new SecureRandom(); public SignupService(UserRepository users, SignupDraftRepository drafts, PasswordEncoder encoder, Clock clock){this.users=users;this.drafts=drafts;this.encoder=encoder;this.clock=clock;} @Transactional public SignupAccountResponse signupAccount(SignupAccountRequest r){if(r==null||r.email()==null||!EMAIL.matcher(r.email()).matches()||r.password()==null||!PASSWORD.matcher(r.password()).matches()||!r.password().equals(r.passwordConfirm())||r.phone()==null||!PHONE.matcher(r.phone()).matches()||r.agreements()==null||!r.agreements().termsOfService()||blank(r.agreements().termsOfServiceVersion())||!r.agreements().privacyPolicy()||blank(r.agreements().privacyPolicyVersion())) throw new InvalidSignupRequestException(); if(users.existsByEmail(r.email())||users.existsByPhone(r.phone())) throw new DuplicateSignupException(); OffsetDateTime now=OffsetDateTime.now(clock), expires=now.plusHours(1); String token="signup_"+Base64.getUrlEncoder().withoutPadding().encodeToString(random.generateSeed(32)); drafts.save(SignupDraft.create(hash(token),r.email(),encoder.encode(r.password()),r.phone(),r.agreements().termsOfService(),r.agreements().termsOfServiceVersion(),r.agreements().privacyPolicy(),r.agreements().privacyPolicyVersion(),expires.toLocalDateTime(),now.toLocalDateTime())); return new SignupAccountResponse(token,expires);} private boolean blank(String v){return v==null||v.isBlank();} private String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} }
